-- mod-temucraft-lostlands: spawns on the new maps (Lost Lands instances and Azshara Crater) and anywhere outside Eastern Kingdoms and Kalimdor
-- 4973 creatures, 1666 objects. Re-runnable.
SET @CRE := 1200000;
SET @GO := 1200000;
SET @GUID_CRE := 5000000;
SET @GUID_GO := 5000000;
DELETE FROM `creature` WHERE `guid` BETWEEN @GUID_CRE+0 AND @GUID_CRE+4972;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN @GUID_CRE+0 AND @GUID_CRE+4972;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN (@GUID_CRE+0)*10 AND (@GUID_CRE+4972)*10+9;
DELETE FROM `gameobject` WHERE `guid` BETWEEN @GUID_GO+0 AND @GUID_GO+1665;
CREATE TEMPORARY TABLE `tmp_shrink` LIKE `creature_addon`;
UPDATE `tmp_shrink` SET `guid`=`guid`+@GUID_CRE;
DROP TEMPORARY TABLE `tmp_shrink`;
CREATE TEMPORARY TABLE `tmp_shrink` LIKE `creature_addon`;
UPDATE `tmp_shrink` SET `guid`=`guid`+@GUID_CRE,`bytes2`=1;
DROP TEMPORARY TABLE `tmp_shrink`;
CREATE TEMPORARY TABLE `tmp_shrink` LIKE `creature_addon`;
UPDATE `tmp_shrink` SET `guid`=`guid`+@GUID_CRE;
DROP TEMPORARY TABLE `tmp_shrink`;
